{"command": "cd /workspace && python3 -c "
import json
runs=[json.loads(l) for l in open('out/cde_runs.jsonl')]
last={}
for r in runs: last[r['target_id']]=r
for k in sorted(last): r=last[k]; print(k, r['cde_level'], r['occupancy_basis'], r['nc_casualty_estimate'], r['ncv'], r['approval_authority'], r['run_at'])
print('total runs:', len(runs))
import datetime
for d in ['2026-10-18','2026-10-19','2026-10-20','2026-10-22']:
    print(d, datetime.date.fromisoformat(d).strftime('%a'))
""}

